begin;
create extension if not exists pgtap with schema extensions;
set search_path to public,extensions;
select no_plan();
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('17900000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp179@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('17900000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('17900000-0000-0000-0000-000000000002','17900000-0000-0000-0000-000000000001','owner');
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp179-browser','mcp179-browser','17900000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('17900000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('17900000-0000-0000-0000-000000000004','17900000-0000-0000-0000-000000000001','17900000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='17900000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('17900000-0000-0000-0000-000000000005','17900000-0000-0000-0000-000000000001','17900000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('17900000-0000-0000-0000-000000000007','17900000-0000-0000-0000-000000000002','Synthetic staff');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('17900000-0000-0000-0000-000000000002',true,'{}','17900000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('17900000-0000-0000-0000-000000000002',true,'{}','17900000-0000-0000-0000-000000000001',now());
select ok(not has_function_privilege('mcp_import','public.confirm_mcp_shift_create(uuid)','EXECUTE'),'MCP cannot confirm');
select ok(not has_table_privilege('authenticated','private.mcp_shift_create_proposals','INSERT,UPDATE,DELETE'),'browser cannot forge proposals');
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"17900000-0000-0000-0000-000000000003","session_id":"17900000-0000-0000-0000-000000000005"}',true);
select throws_ok($$select public.propose_mcp_shift_create('17900000-0000-0000-0000-000000000002','17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000007','2026-12-01 00:00+00','2026-12-01 01:00+00')$$,'42501','mcp_shift_create_unavailable','default off');
reset role;
insert into private.mcp_shift_create_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('17900000-0000-0000-0000-000000000002',true,'{}','17900000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select throws_ok($$select public.propose_mcp_shift_create('17900000-0000-0000-0000-000000000099','17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000007','2026-12-01 00:00+00','2026-12-01 01:00+00')$$,'42501','mcp_shift_read_unavailable','other organization rejected');
select set_config('test.proposal',public.propose_mcp_shift_create('17900000-0000-0000-0000-000000000002','17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000007','2026-12-01 00:00+00','2026-12-01 01:00+00')->>'proposal_id',true);
select is(public.get_mcp_shift_create_result('17900000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','confirmation_required','no confirmation does not create');
reset role;
select is((select count(*)::integer from public.shifts where organization_id='17900000-0000-0000-0000-000000000002'),0,'no shift before confirmation');
update public.organization_members set role='member' where organization_id='17900000-0000-0000-0000-000000000002' and user_id='17900000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp179-browser"}',true);
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.proposal')::uuid)$$,'42501','proposal_unavailable','permission loss rejects confirmation');
reset role;
update public.organization_members set role='owner' where organization_id='17900000-0000-0000-0000-000000000002' and user_id='17900000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp179-browser"}',true);
select is(public.get_mcp_shift_create_proposal(current_setting('test.proposal')::uuid)->>'client_name','Synthetic client','browser sees fixed proposal');
select is(public.confirm_mcp_shift_create(current_setting('test.proposal')::uuid)->>'status','created','confirmed proposal creates');
select is(public.confirm_mcp_shift_create(current_setting('test.proposal')::uuid)->>'newly_created','false','repeat returns existing result');
reset role;
select is((select count(*)::integer from public.shifts where organization_id='17900000-0000-0000-0000-000000000002'),1,'repeat does not duplicate');
select is((select count(*)::integer from public.audit_events where organization_id='17900000-0000-0000-0000-000000000002' and action_type='shift.create'),1,'creation audited once');
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"17900000-0000-0000-0000-000000000003","session_id":"17900000-0000-0000-0000-000000000005"}',true);
select is(public.get_mcp_shift_create_result('17900000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'google_sync_status','pending_upsert','sync pending reported');
select set_config('test.conflict',public.propose_mcp_shift_create('17900000-0000-0000-0000-000000000002','17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000007','2026-12-01 00:30+00','2026-12-01 01:30+00')->>'proposal_id',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp179-browser"}',true);
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.conflict')::uuid)$$,'23505','shift_conflict','conflict rejected');
reset role;
select is((select count(*)::integer from public.shifts where organization_id='17900000-0000-0000-0000-000000000002'),1,'conflict created nothing');
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"17900000-0000-0000-0000-000000000003","session_id":"17900000-0000-0000-0000-000000000005"}',true);
select set_config('test.revoked',public.propose_mcp_shift_create('17900000-0000-0000-0000-000000000002','17900000-0000-0000-0000-000000000006','17900000-0000-0000-0000-000000000007','2026-12-02 00:00+00','2026-12-02 01:00+00')->>'proposal_id',true);
reset role;
update auth.oauth_consents set revoked_at=clock_timestamp() where id='17900000-0000-0000-0000-000000000004';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"17900000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp179-browser"}',true);
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.revoked')::uuid)$$,'42501','proposal_unavailable','revoked OAuth consent rejects confirmation');
reset role;
update auth.oauth_consents set revoked_at=null where id='17900000-0000-0000-0000-000000000004';
update private.mcp_shift_create_proposals set expires_at=clock_timestamp()-interval '1 second' where id=current_setting('test.revoked')::uuid;
set local role authenticated;
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.revoked')::uuid)$$,'22023','proposal_expired','expired confirmation rejects');
reset role;
select is((select count(*)::integer from public.shifts where organization_id='17900000-0000-0000-0000-000000000002'),1,'revocation and expiry created nothing');
update private.mcp_shift_create_proposals set expires_at=clock_timestamp()+interval '5 minutes' where id=current_setting('test.revoked')::uuid;
update public.clients set name='Changed synthetic client' where id='17900000-0000-0000-0000-000000000006';
set local role authenticated;
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.revoked')::uuid)$$,'22023','proposal_changed','changed display identity requires a new proposal');
reset role;
update public.clients set name='Synthetic client' where id='17900000-0000-0000-0000-000000000006';
create function pg_temp.reject_shift_create_audit() returns trigger language plpgsql as $$begin if new.action_type='shift.create' then raise exception 'audit_unavailable'; end if; return new; end$$;
create trigger test_reject_shift_create_audit before insert on public.audit_events for each row execute function pg_temp.reject_shift_create_audit();
set local role authenticated;
select throws_ok($$select public.confirm_mcp_shift_create(current_setting('test.revoked')::uuid)$$,'P0001','audit_unavailable','audit failure aborts creation');
reset role;
select is((select count(*)::integer from public.shifts where organization_id='17900000-0000-0000-0000-000000000002'),1,'audit failure rolled back shift');
select is((select shift_id from private.mcp_shift_create_proposals where id=current_setting('test.revoked')::uuid),null::uuid,'audit failure did not consume proposal');
select * from finish();
rollback;
